using System.Text.Json;
using Cecil = Mono.Cecil;

namespace Meziantou.Framework.Assertions.Architecture.Tests;

// Compares the types each type depends on with the ones an independent reader, built on Mono.Cecil, finds in the same assembly.
// The oracle applies the same rules: code generated by the compiler belongs to the type that declares it, the compiler attributes are ignored,
// and the type itself, System.Void and the types generated by the compiler are not dependencies.
public sealed class CecilDifferentialTests
{
    private static readonly HashSet<string> CompilerAttributes = new(StringComparer.Ordinal)
    {
        "System.ParamArrayAttribute",
        "System.Diagnostics.DebuggerBrowsableAttribute",
        "System.Diagnostics.DebuggerHiddenAttribute",
        "System.Diagnostics.DebuggerStepThroughAttribute",
        "System.Diagnostics.CodeAnalysis.SetsRequiredMembersAttribute",
        "System.Reflection.DefaultMemberAttribute",
        "System.Runtime.CompilerServices.AsyncIteratorStateMachineAttribute",
        "System.Runtime.CompilerServices.AsyncStateMachineAttribute",
        "System.Runtime.CompilerServices.CompilerFeatureRequiredAttribute",
        "System.Runtime.CompilerServices.CompilerGeneratedAttribute",
        "System.Runtime.CompilerServices.DecimalConstantAttribute",
        "System.Runtime.CompilerServices.DynamicAttribute",
        "System.Runtime.CompilerServices.ExtensionAttribute",
        "System.Runtime.CompilerServices.ExtensionMarkerAttribute",
        "System.Runtime.CompilerServices.IsByRefLikeAttribute",
        "System.Runtime.CompilerServices.IsReadOnlyAttribute",
        "System.Runtime.CompilerServices.IsUnmanagedAttribute",
        "System.Runtime.CompilerServices.IteratorStateMachineAttribute",
        "System.Runtime.CompilerServices.NativeIntegerAttribute",
        "System.Runtime.CompilerServices.NullableAttribute",
        "System.Runtime.CompilerServices.NullableContextAttribute",
        "System.Runtime.CompilerServices.NullablePublicOnlyAttribute",
        "System.Runtime.CompilerServices.ParamCollectionAttribute",
        "System.Runtime.CompilerServices.PreserveBaseOverridesAttribute",
        "System.Runtime.CompilerServices.RefSafetyRulesAttribute",
        "System.Runtime.CompilerServices.RequiredMemberAttribute",
        "System.Runtime.CompilerServices.ScopedRefAttribute",
        "System.Runtime.CompilerServices.TupleElementNamesAttribute",
    };

    public static TheoryData<string> Assemblies() =>
    [
        typeof(ArchitectureModel).Assembly.Location,
        typeof(CecilDifferentialTests).Assembly.Location,
        typeof(Cecil.ModuleDefinition).Assembly.Location,
        typeof(JsonSerializer).Assembly.Location,
    ];

    [Theory]
    [MemberData(nameof(Assemblies))]
    public void DependenciesMatchMonoCecil(string path)
    {
        var options = new ArchitectureLoadOptions { ReadSourceLocations = false };
        options.AssemblyPaths.Add(path);
        var architecture = ArchitectureModel.Load(options);

        var expected = GetCecilDependencies(path, architecture);
        var differences = new List<string>();
        foreach (var type in architecture.Types)
        {
            var actual = type.Dependencies.Select(dependency => dependency.Target.FullName).ToHashSet(StringComparer.Ordinal);
            var expectedTargets = expected.GetValueOrDefault(type.FullName) ?? [];
            foreach (var missing in expectedTargets.Except(actual, StringComparer.Ordinal).Order(StringComparer.Ordinal))
            {
                differences.Add($"{type.FullName}: missing {missing}");
            }

            foreach (var extra in actual.Except(expectedTargets, StringComparer.Ordinal).Order(StringComparer.Ordinal))
            {
                differences.Add($"{type.FullName}: unexpected {extra}");
            }
        }

        Assert.NotEmpty(expected);
        Assert.Equal(expected.Keys.Order(StringComparer.Ordinal).ToArray(), architecture.Types.Select(type => type.FullName).Order(StringComparer.Ordinal).ToArray());
        Assert.Empty(differences, string.Join('\n', differences.Take(50)));
    }

    private static Dictionary<string, HashSet<string>> GetCecilDependencies(string path, ArchitectureModel architecture)
    {
        using var module = Cecil.ModuleDefinition.ReadModule(path);
        var allTypes = module.GetTypes().ToList();
        var generatedTypes = allTypes.Where(type => architecture.FindType(GetName(type)) is null).Select(GetName).ToHashSet(StringComparer.Ordinal);

        var result = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
        foreach (var type in allTypes)
        {
            var name = GetName(type);
            if (generatedTypes.Contains(name))
                continue;

            var targets = new HashSet<string>(StringComparer.Ordinal);
            CollectType(type, targets, isGenerated: false);
            foreach (var generatedType in allTypes)
            {
                if (generatedTypes.Contains(GetName(generatedType)) && GetOwner(generatedType) == type)
                {
                    CollectType(generatedType, targets, isGenerated: true);
                }
            }

            targets.RemoveWhere(target => string.Equals(target, name, StringComparison.Ordinal)
                || target is "System.Void"
                || generatedTypes.Contains(target)
                || (architecture.FindType(target) is null && target.Split('+').Any(segment => segment.Split('.')[^1].StartsWith("<", StringComparison.Ordinal))));
            result.Add(name, targets);
        }

        return result;

        Cecil.TypeDefinition? GetOwner(Cecil.TypeDefinition type)
        {
            for (var current = type.DeclaringType; current is not null; current = current.DeclaringType)
            {
                if (!generatedTypes.Contains(GetName(current)))
                    return current;
            }

            return null;
        }
    }

    private static void CollectType(Cecil.TypeDefinition type, HashSet<string> targets, bool isGenerated)
    {
        if (!isGenerated)
        {
            if (type.BaseType is not null)
            {
                AddType(type.BaseType, targets);
            }

            foreach (var @interface in type.Interfaces)
            {
                AddType(@interface.InterfaceType, targets);
            }

            AddAttributes(type.CustomAttributes, targets);
            AddConstraints(type.GenericParameters, targets);
            foreach (var property in type.Properties)
            {
                AddType(property.PropertyType, targets);
                foreach (var parameter in property.Parameters)
                {
                    AddType(parameter.ParameterType, targets);
                }

                AddAttributes(property.CustomAttributes, targets);
            }

            foreach (var @event in type.Events)
            {
                AddType(@event.EventType, targets);
                AddAttributes(@event.CustomAttributes, targets);
            }
        }

        foreach (var field in type.Fields)
        {
            if (isGenerated)
            {
                AddType(field.FieldType, targets);
            }
            else if (!field.Name.StartsWith("<", StringComparison.Ordinal))
            {
                AddType(field.FieldType, targets);
                AddAttributes(field.CustomAttributes, targets);
            }
        }

        foreach (var method in type.Methods)
        {
            var isGeneratedMethod = isGenerated || (method.Name.StartsWith("<", StringComparison.Ordinal) && method.Name is not "<Main>$");
            AddType(method.ReturnType, targets);
            foreach (var parameter in method.Parameters)
            {
                AddType(parameter.ParameterType, targets);
            }

            if (!isGeneratedMethod)
            {
                AddAttributes(method.CustomAttributes, targets);
                AddAttributes(method.MethodReturnType.CustomAttributes, targets);
                foreach (var parameter in method.Parameters)
                {
                    AddAttributes(parameter.CustomAttributes, targets);
                }
            }

            AddConstraints(method.GenericParameters, targets);
            if (!method.HasBody)
                continue;

            foreach (var variable in method.Body.Variables)
            {
                AddType(variable.VariableType, targets);
            }

            foreach (var handler in method.Body.ExceptionHandlers)
            {
                if (handler.HandlerType == Cecil.Cil.ExceptionHandlerType.Catch && handler.CatchType is not null)
                {
                    AddType(handler.CatchType, targets);
                }
            }

            foreach (var instruction in method.Body.Instructions)
            {
                switch (instruction.Operand)
                {
                    case Cecil.GenericInstanceMethod genericMethod:
                        AddType(genericMethod.DeclaringType, targets);
                        foreach (var argument in genericMethod.GenericArguments)
                        {
                            AddType(argument, targets);
                        }

                        break;

                    case Cecil.MethodReference methodReference:
                        AddType(methodReference.DeclaringType, targets);
                        break;

                    case Cecil.FieldReference fieldReference:
                        AddType(fieldReference.DeclaringType, targets);
                        break;

                    case Cecil.TypeReference typeReference:
                        AddType(typeReference, targets);
                        break;

                    case Cecil.CallSite callSite:
                        AddType(callSite.ReturnType, targets);
                        foreach (var parameter in callSite.Parameters)
                        {
                            AddType(parameter.ParameterType, targets);
                        }

                        break;
                }
            }
        }
    }

    private static void AddConstraints(IEnumerable<Cecil.GenericParameter> parameters, HashSet<string> targets)
    {
        foreach (var parameter in parameters)
        {
            foreach (var constraint in parameter.Constraints)
            {
                AddType(constraint.ConstraintType, targets);
            }
        }
    }

    private static void AddAttributes(IEnumerable<Cecil.CustomAttribute> attributes, HashSet<string> targets)
    {
        foreach (var attribute in attributes)
        {
            var name = GetName(attribute.AttributeType);
            if (CompilerAttributes.Contains(name))
                continue;

            AddType(attribute.AttributeType, targets);
            try
            {
                foreach (var argument in attribute.ConstructorArguments)
                {
                    AddArgument(argument);
                }

                foreach (var argument in attribute.Properties.Concat(attribute.Fields))
                {
                    AddArgument(argument.Argument);
                }
            }
            catch (Exception ex) when (ex is Cecil.AssemblyResolutionException or InvalidOperationException or NotSupportedException)
            {
                // The values cannot be decoded when an enum type cannot be resolved; the library reads no value either
            }
        }

        void AddArgument(Cecil.CustomAttributeArgument argument)
        {
            switch (argument.Value)
            {
                case Cecil.TypeReference type:
                    AddType(type, targets);
                    break;

                case Cecil.CustomAttributeArgument boxed:
                    AddArgument(boxed);
                    break;

                case Cecil.CustomAttributeArgument[] array:
                    foreach (var item in array)
                    {
                        AddArgument(item);
                    }

                    break;
            }
        }
    }

    private static void AddType(Cecil.TypeReference type, HashSet<string> targets)
    {
        switch (type)
        {
            case Cecil.GenericParameter:
                break;

            case Cecil.GenericInstanceType genericInstance:
                AddType(genericInstance.ElementType, targets);
                foreach (var argument in genericInstance.GenericArguments)
                {
                    AddType(argument, targets);
                }

                break;

            case Cecil.FunctionPointerType functionPointer:
                AddType(functionPointer.ReturnType, targets);
                foreach (var parameter in functionPointer.Parameters)
                {
                    AddType(parameter.ParameterType, targets);
                }

                break;

            case Cecil.TypeSpecification specification:
                AddType(specification.ElementType, targets);
                break;

            default:
                targets.Add(GetName(type));
                break;
        }
    }

    private static string GetName(Cecil.TypeReference type) => type.FullName.Replace('/', '+');
}
